20260924	{"-- CareFur chat attachment storage.\n-- Run once in Supabase SQL Editor.\n\ninsert into storage.buckets (id, name, public)\nvalues ('chat-attachments', 'chat-attachments', true)\non conflict (id) do update set public = true","-- Owners upload only inside their own auth.uid() folder.\ndrop policy if exists \\"carefur owners upload chat attachments\\" on storage.objects","create policy \\"carefur owners upload chat attachments\\"\non storage.objects for insert\nto authenticated\nwith check (\n  bucket_id = 'chat-attachments'\n  and (storage.foldername(name))[1] = auth.uid()::text\n)","drop policy if exists \\"carefur owners read chat attachments\\" on storage.objects","create policy \\"carefur owners read chat attachments\\"\non storage.objects for select\nto authenticated\nusing (bucket_id = 'chat-attachments')","-- Public bucket URLs are used in message payloads. If you later make the bucket\n-- private, replace getPublicUrl() in ChatScreen with signed URLs."}	chat_attachments
